#!/usr/bin/env python3
"""
Round 180b (culprits), 5 October 2026. Needs round 179b.

Aqua, a glass-and-water basemap.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 180b (5 October)\n\nNeeds round 179b (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Asked 5 October: another basemap in the look of the owner's two pictures\n  (a seaside room and a desk by a window, washed in pale aqua, white and\n  glass). New basemap Aqua (kind \"aqua\"), on the menu after Bioluminescent.\n- Made like Woodlands, from the real Earth: the Sentinel-2 cloudless picture\n  (EOX, read through woodComposite) re-coloured pixel by pixel\n  (aquaPaintPixels, in two Web Workers): what grows on teals from lagoon\n  teal to pale sea-glass, bare ground on cool pearl greys to near white,\n  snow white, water in clear blues; half sharp, half softened (soft focus);\n  bright ground blooms softly into its surroundings; a thin white haze.\n- Over it: the sea by depth from pale aqua shallows to deep blue (sea-dem),\n  a high soft north-west light with white highlights and teal shadow\n  (outline-dem), a white haze over low land, lakes and rivers in aqua,\n  white roads with a faint aqua glow, frosted white buildings from zoom 13,\n  fine teal borders, a pale aqua-to-white sky on the globe.\n- Names: THEMED_NAMES.aqua, Jost (already in map/glyphs), dark sea-teal on a\n  white halo; themedWhich and themedSync take \"aqua\" with atlas and\n  satellite. Layer colours default to \"deep\" on it (pale ground).\n- Hues checked by test: every painted colour is teal to cobalt (172-227) or a\n  pale grey. Not seen against the real imagery: EOX is blocked here.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round180b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 179b" not in h.read_text(encoding="utf-8"):
        sys.exit("round180b: round 179b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round180b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round180b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round180b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
